<?php
namespace Tests\Feature;use Tests\TestCase;use Illuminate\Foundation\Testing\RefreshDatabase;use App\Models\User;class ApiSmokeTest extends TestCase{use RefreshDatabase;public function test_health_endpoint_works():void{$this->get('/up')->assertOk();}public function test_invalid_login_is_rejected():void{$this->postJson('/api/login',['email'=>'missing@example.com','password'=>'wrong-password'])->assertUnprocessable();}public function test_admin_can_access_courses():void{$this->seed();$admin=User::where('role','admin')->first();$this->actingAs($admin)->getJson('/api/courses')->assertOk();}}
